// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.storageimport com.roshan.persona.brain.skill.CredentialVaultInterfaceimport com.roshan.persona.security.applock.AppLockManagerimport com.roshan.persona.security.applock.AppLockStateimport com.roshan.persona.security.keystore.KeystoreManagerimport com.roshan.persona.security.supplychain.ScanResultimport com.roshan.persona.security.supplychain.SupplyChainMonitorimport com.roshan.persona.security.supplychain.ThreatStateimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Credential Vault (Module 12, Pillar 4). * * Strategy §12.4 — real implementation of Brain's [CredentialVaultInterface]. * Replaces Brain's `InMemoryCredentialVault` stub (which was lost on process * death and had no encryption). * * ## What it stores * *   - **API keys** — OpenAI, Anthropic, Gemini, etc. (used by :feature:llm). *   - **User credentials** — passwords for third-party services that the *     user wants NOUS to remember. *   - **OAuth tokens** — refresh tokens for services like Google Calendar. * * ## How it's stored * *   - **Outer layer**: EncryptedSharedPreferences (MasterKey in AndroidKeystore). *   - **Inner layer**: AES-256-GCM via [KeystoreManager] under alias *     [CREDENTIAL_KEY_ALIAS] (separate from the master key — defense in depth). * * ## Access control * * If [AppLockManager] is enabled and the app is currently [AppLockState.Locked], * credential access is REFUSED — [retrieveCredential] returns null. This * prevents a background service (or attacker with shell access) from reading * credentials while the app is locked. * * ## Brain's view * * Brain's [CredentialVaultInterface] takes `skillId` and `key` parameters * (not `alias`). We compose the storage alias as `skillId::key` so that * different skills' credentials don't collide. * * @see CredentialVaultInterface * @see EncryptedStorage */@Singletonclass CredentialVaultImpl @Inject constructor(    private val encryptedStorage: EncryptedStorage,    private val keystoreManager: KeystoreManager,    private val appLockManager: AppLockManager,    private val supplyChainMonitor: SupplyChainMonitor,) : CredentialVaultInterface {    /**     * Cached [SupplyChainMonitor.scan] result. Refreshed on a 10-minute TTL     * so that the vault doesn't re-scan the runtime on every read (the     * scan walks `/proc/self/maps`, PackageManager, and filesystem paths).     */    @Volatile private var cachedScan: ScanResult? = null    @Volatile private var cachedScanAt: Long = 0L    /**     * Ensure the per-vault encryption key exists. Called lazily on first     * store/retrieve — creates the key with StrongBox/TEE auto-select if     * it doesn't exist yet.     */    private fun ensureKey(): Boolean {        if (!keystoreManager.keyExists(CREDENTIAL_KEY_ALIAS)) {            val level = keystoreManager.generateKey(CREDENTIAL_KEY_ALIAS, requireAuth = false)            if (level == null) {                Timber.tag("NOUS.Security").w("Failed to generate credential vault key")                return false            }        }        return true    }    /**     * Compute the outer preference key from (skillId, key).     *     * Format: `vault::<skillId>::<key>` — namespaced to avoid collisions     * with other EncryptedSharedPreferences users.     */    private fun prefKey(skillId: String, key: String): String = "vault::$skillId::$key"    /**     * Compute the prefix for listing all credentials under a skill.     */    private fun prefPrefix(skillId: String): String = "vault::$skillId::"    /**     * Store a credential encrypted at rest.     *     * Refuses to operate if [SupplyChainMonitor] reports [ThreatState.COMPROMISED]     * (e.g., Frida server actively hooking the process, root binary present).     *     * @param skillId the skill that owns this credential (e.g., "openai").     * @param key the credential key (e.g., "api_key").     * @param value the credential value (the actual API key / password).     * @throws SecurityException if the device is currently compromised.     */    override fun storeCredential(skillId: String, key: String, value: String) {        ensureSupplyChainClean()        if (!ensureKey()) return        val ok = encryptedStorage.storeDoubleEncrypted(            outerKey = prefKey(skillId, key),            innerKeyAlias = CREDENTIAL_KEY_ALIAS,            value = value,        )        if (ok) {            Timber.tag("NOUS.Security").v("Stored credential: skill=%s, key=%s", skillId, key)        }    }    /**     * Retrieve a credential.     *     * Returns `null` if:     *   - The device is compromised (see class KDoc on SupplyChainMonitor).     *   - The app is locked (see class KDoc on access control).     *   - The credential doesn't exist.     *   - Decryption fails (corrupted ciphertext or rotated key).     *     * @param skillId the skill that owns this credential.     * @param key the credential key.     * @return the plaintext credential, or null.     * @throws SecurityException if the device is currently compromised.     */    override fun getCredential(skillId: String, key: String): String? {        // ─── Supply-chain gate: refuse on COMPROMISED (Frida, root, etc.) ─        ensureSupplyChainClean()        // ─── Access control: refuse if app is locked ───────────────────        // Note: we check this synchronously (not via StateFlow) so that        // background callers (skills executing in IO dispatcher) see the        // current lock state at the time of the call.        if (appLockManager.isLocked()) {            Timber.tag("NOUS.Security").w(                "Credential access REFUSED: app is locked (skill=%s, key=%s)",                skillId, key,            )            return null        }        return encryptedStorage.readDoubleEncrypted(            outerKey = prefKey(skillId, key),            innerKeyAlias = CREDENTIAL_KEY_ALIAS,        )    }    /**     * Delete a single credential.     */    override fun deleteCredential(skillId: String, key: String) {        encryptedStorage.remove(prefKey(skillId, key))    }    /**     * Delete ALL credentials for a skill (used when a skill is uninstalled).     */    override fun deleteAllForSkill(skillId: String) {        val prefix = prefPrefix(skillId)        for (k in encryptedStorage.keys().toList()) {            if (k.startsWith(prefix)) encryptedStorage.remove(k)        }    }    /**     * List all credential aliases (across all skills).     *     * Returns a list of `"skillId::key"` strings — for the Settings UI to     * show what credentials are stored. The actual credential values are     * NOT returned (they require authentication).     *     * @param requireAuth if true (default), only returns aliases when the     *   app is unlocked. If false, returns aliases even when locked     *   (used by the settings UI to show a count).     */    fun listCredentialAliases(requireAuth: Boolean = true): List<String> {        if (requireAuth && appLockManager.isLocked()) return emptyList()        return encryptedStorage.keys()            .filter { it.startsWith("vault::") }            .map { it.removePrefix("vault::") }            .sorted()    }    /**     * Wipe ALL credentials. Use for "delete all my data" — clears the     * encrypted storage AND the underlying Keystore key.     */    fun wipeAll() {        for (k in encryptedStorage.keys().toList()) {            if (k.startsWith("vault::")) encryptedStorage.remove(k)        }        keystoreManager.deleteKey(CREDENTIAL_KEY_ALIAS)    }    /**     * Ensure the device is not currently compromised before granting vault access.     *     * Uses a 10-minute TTL cache so we don't scan `/proc/self/maps` +     * PackageManager + filesystem on every call. If the cached scan is     * stale, we re-scan synchronously.     *     * @throws SecurityException if [SupplyChainMonitor.scan] returns     *   [ThreatState.COMPROMISED].     */    private fun ensureSupplyChainClean() {        val now = System.currentTimeMillis()        val cached = cachedScan        val scan = if (cached != null && now - cachedScanAt < SUPPLY_CHAIN_CACHE_TTL_MS) {            cached        } else {            val fresh = supplyChainMonitor.scan()            cachedScan = fresh            cachedScanAt = now            fresh        }        if (scan.state == ThreatState.COMPROMISED) {            val threatNames = scan.threats.joinToString { it.name }            Timber.tag("NOUS.Security").w(                "Credential vault DISABLED — device compromised: threats=[%s]",                threatNames,            )            throw SecurityException("Device compromised — credential vault disabled")        }    }    private companion object {        /** Keystore alias for the inner-layer credential encryption key. */        const val CREDENTIAL_KEY_ALIAS = "nous.credential_vault.v1"        /** TTL for the cached supply-chain scan (10 minutes). */        const val SUPPLY_CHAIN_CACHE_TTL_MS = 10L * 60L * 1000L    }}